module partition_puzzle(input clk, input rst_n, input start, input [7:0] v0, v1, v2, v3, v4, v5, v6, v7, input [3:0] n, input [3:0] k, output reg [7:0] max_score, output reg done);reg [7:0] captured_v [7:0];reg [3:0] captured_n, captured_k;reg [3:0] lpf_arr [7:0];reg [7:0] max_score_reg;reg done_reg;reg [4:0] state;function automatic [3:0] lpf_of_num;input [7:0] num;begin if (num == 0) return 0; if (num % 31 ==0) return 31; if (num %29 ==0) return29; if (num%23==0)return23; if (num%19==0)return19; if (num%17==0)return17; if (num%13==0)return13; if (num%11==0)return11; if (num%7==0)return7; if (num%5==0)return5; if (num%3==0)return3; if (num%2==0)return2; return 0;endfunctionalways @(posedge clk) begin if (!rst_n) begin captured_v <= 8'b0; captured_n <=4'b0; captured_k <=4'b0; lpf_arr <=8'b0; max_score_reg <=8'b0; done_reg <=1'b0; state <=4'b0; end else begin case (state) 4'b0: // IDLE if (start ==1'b1) begin captured_v <= {v0, v1, v2, v3, v4, v5, v6, v7}; captured_n <= n; captured_k <= k; state <=4'b1; end max_score_reg <=8'b0; done_reg <=1'b0; 4'b1: // COMPUTE_PRIMES lpf_arr[0] = captured_n >0 ? lpf_of_num(captured_v[0]) :4'b0; lpf_arr[1] = captured_n >1 ? lpf_of_num(captured_v[1]) :4'b0; lpf_arr[2] = captured_n >2 ? lpf_of_num(captured_v[2]) :4'b0; lpf_arr[3] = captured_n >3 ? lpf_of_num(captured_v[3]) :4'b0; lpf_arr[4] = captured_n >4 ? lpf_of_num(captured_v[4]) :4'b0; lpf_arr[5] = captured_n >5 ? lpf_of_num(captured_v[5]) :4'b0; lpf_arr[6] = captured_n >6 ? lpf_of_num(captured_v[6]) :4'b0; lpf_arr[7] = captured_n >7 ? lpf_of_num(captured_v[7]) :4'b0; state <=4'b2; 4'b2: // GENERATE_PARTITIONS state <=4'b3; 4'b3: // EVALUATE_SCORES if (captured_k ==4'd1) begin reg [3:0] min_val =4'd31; if (captured_n >0) min_val = min(min_val, lpf_arr[0]); if (captured_n >1) min_val = min(min_val, lpf_arr[1]); if (captured_n >2) min_val = min(min_val, lpf_arr[2]); if (captured_n >3) min_val = min(min_val, lpf_arr[3]); if (captured_n >4) min_val = min(min_val, lpf_arr[4]); if (cap